  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [240+Math.cos(t*0.25)*180*Math.cos(t*0.15), 120+Math.sin(t*0.25)*180*Math.sin(t*0.15), 0.05, 3.0, 0.6],
    [240+Math.sin(t*0.45)*150*Math.cos(t*0.2+1), 120+Math.cos(t*0.45)*150*Math.sin(t*0.2+1), 0.11, 1.3, 1.3],
    [240+Math.cos(t*0.55+2)*120, 120+Math.sin(t*0.55+2)*100, 0.045, 2.8, 0.5],
    [240+Math.sin(t*0.18+3)*200, 120+Math.cos(t*0.18+3)*80, 0.13, 1.1, 1.4]
  ];
  let aS = 0, iS = 0, mS = 0, tW = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    mS += Math.sin(d*f*1.3 - t*sp*0.8 + 0.7) * w * 0.5;
    tW += w;
  }
  const act = aS/tW, inh = iS/tW, mod = mS/tW;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.08+t*1.8)*Math.cos(sy*0.06-t*1.3)*0.15;
