  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + mod*0.4)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3 + Math.tanh((Math.sin(sx*0.08+t*0.3)*Math.cos(sy*0.07-t*0.2)))*0.15;
  const vignette = 1 - Math.sqrt((x-cx)**2+(y-cy)**2)/340;
  const blend = reaction*0.65 + cell*0.2 + mod*0.15;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const pal = [[5,12,55],[10,55,95],[15,110,120],[40,160,130],[140,190,90],[220,200,60],[230,150,55],[210,90,60],[180,50,70],[120,30,80],[60,20,65],[15,15,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
