  const glow = Math.max(0, 1-Math.abs(reaction)*2)*0.1;
  const vf = vignette*lum*edge+glow;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*vf)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*vf)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*vf)|0
  ];
}
